package cn.zj.zjmarket.infrastructure.dao;
import cn.zj.zjmarket.infrastructure.dao.po.*;
import org.apache.ibatis.annotations.*;
import java.util.List;
public interface ITradeDao {
 @Select("SELECT t.order_id FROM b_trade_coordination t JOIN b_market_order o ON o.order_id=t.order_id WHERE o.business_status<>'CLOSED' AND ((o.business_status='PROCESSING' AND o.reserve_wait_deadline_ms<=CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED) AND o.close_request IS NULL) OR (o.business_status='WAITING_PAYMENT' AND o.a_deadline_due_ms<=CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED) AND t.run_state='DONE' AND t.paused=0 AND o.review_required=0) OR (t.paused=0 AND (o.review_required=0 OR t.auth_probe=1) AND t.intent IN ('RESERVE','QUERY','CLOSE') AND t.next_attempt_ms<=CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED) AND (t.run_state='READY' OR (t.run_state='LEASED' AND t.lease_until_ms<=CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED))))) ORDER BY t.next_attempt_ms,t.order_id LIMIT #{limit}") List<String> due(int limit);
 @Select("SELECT user_id AS userId,goods_id AS goodsId FROM b_market_order WHERE order_id=#{id}") OrderLocatorRow locate(String id);
 @Select("SELECT user_id FROM b_user WHERE user_id=#{id} FOR SHARE") String lockUser(String id);
 @Select("SELECT order_id FROM b_market_order WHERE order_id=#{id} FOR UPDATE") String lockOrder(String id);
 @Select("SELECT state FROM b_inventory_reservation WHERE order_id=#{id} FOR UPDATE") String lockReservation(String id);
 @Select("SELECT order_id AS orderId,intent,intent_version AS intentVersion,run_state AS runState,paused,task_version AS taskVersion,next_attempt_ms AS nextAttempt,lease_token AS leaseToken,lease_until_ms AS leaseUntil,attempt_count AS attemptCount,failure_count AS failureCount,alerted,auth_check_required AS authCheckRequired,auth_probe AS authProbe,last_error AS lastError FROM b_trade_coordination WHERE order_id=#{id} FOR UPDATE") TradeTaskRow lockTask(String id);
 @Update("UPDATE b_trade_coordination SET intent=#{intent},intent_version=#{intentVersion},run_state=#{runState},paused=#{paused},task_version=#{taskVersion},next_attempt_ms=#{nextAttempt},lease_token=#{leaseToken},lease_until_ms=#{leaseUntil},attempt_count=#{attemptCount},failure_count=#{failureCount},alerted=#{alerted},last_error=#{error} WHERE order_id=#{orderId}") int task(@Param("orderId")String orderId,@Param("intent")String intent,@Param("intentVersion")long intentVersion,@Param("runState")String runState,@Param("paused")boolean paused,@Param("taskVersion")long taskVersion,@Param("nextAttempt")long nextAttempt,@Param("leaseToken")String leaseToken,@Param("leaseUntil")Long leaseUntil,@Param("attemptCount")long attemptCount,@Param("failureCount")long failureCount,@Param("alerted")boolean alerted,@Param("error")String error);
 @Update("UPDATE b_market_order SET may_have_dispatched=1,order_version=order_version+1,updated_at_ms=#{now} WHERE order_id=#{id} AND may_have_dispatched=0") int mark(@Param("id")String id,@Param("now")long now);
 @Update("<script>UPDATE b_market_order SET business_status=#{status},review_required=#{review},last_error=#{error},order_version=order_version+1,updated_at_ms=#{now}<if test='evidence != null'>,a_evidence=#{evidence},a_evidence_hash=#{hash},a_received_at_ms=#{received},a_deadline_due_ms=#{deadline}</if> WHERE order_id=#{id}</script>") int result(@Param("id")String id,@Param("status")String status,@Param("review")boolean review,@Param("error")String error,@Param("now")long now,@Param("evidence")String evidence,@Param("hash")String hash,@Param("received")long received,@Param("deadline")Long deadline);
 @Update("UPDATE b_market_order SET business_status='CLOSING',close_request=#{body},close_request_hash=#{hash},close_reason=#{reason},last_error=#{error},order_version=order_version+1,updated_at_ms=#{now} WHERE order_id=#{id} AND close_request IS NULL") int closeIntent(@Param("id")String id,@Param("body")String body,@Param("hash")String hash,@Param("reason")String reason,@Param("error")String error,@Param("now")long now);
 @Insert("INSERT INTO b_trade_attempt(attempt_id,order_id,intent,intent_version,token_hash,request_id,method,started_at_ms) VALUES(#{id},#{lease.orderId},#{lease.intent},#{lease.intentVersion},#{hash},#{request},#{method},#{now})") int attempt(@Param("id")String id,@Param("lease")cn.zj.zjmarket.domain.order.model.valobj.TradeLease lease,@Param("hash")String hash,@Param("request")String request,@Param("method")String method,@Param("now")long now);
 @Update("UPDATE b_trade_attempt SET finished_at_ms=#{now},code=#{code},result_hash=#{hash},stale=#{stale} WHERE attempt_id=#{id} AND finished_at_ms IS NULL") int finish(@Param("id")String id,@Param("now")long now,@Param("code")String code,@Param("hash")String hash,@Param("stale")boolean stale);

 @Select("SELECT order_id AS orderId,intent,intent_version AS intentVersion,run_state AS runState,paused,task_version AS taskVersion,next_attempt_ms AS nextAttempt,lease_token AS leaseToken,lease_until_ms AS leaseUntil,attempt_count AS attemptCount,failure_count AS failureCount,alerted,auth_check_required AS authCheckRequired,auth_probe AS authProbe,last_error AS lastError FROM b_trade_coordination WHERE order_id=#{id}") TradeTaskRow readTask(String id);
 @Select("SELECT CAST(close_request AS CHAR) AS request,COALESCE(close_request_hash,'') AS hash,CAST(close_evidence AS CHAR) AS evidence,close_evidence_hash AS evidenceHash,a_deadline_due_ms AS deadline FROM b_market_order WHERE order_id=#{id}") cn.zj.zjmarket.infrastructure.dao.po.CloseRow closeRow(String id);
 @Update("UPDATE b_trade_coordination SET paused=#{paused},auth_check_required=#{required},auth_probe=#{probe} WHERE order_id=#{id}") int flags(@Param("id")String id,@Param("paused")boolean paused,@Param("required")boolean required,@Param("probe")boolean probe);
 @Update("UPDATE b_market_order SET close_evidence=#{body},close_evidence_hash=#{hash} WHERE order_id=#{id}") int closeEvidence(@Param("id")String id,@Param("body")String body,@Param("hash")String hash);
 @Update("UPDATE b_inventory_reservation SET state='RELEASED',resolved_at_ms=#{now},resolution_basis=#{basis} WHERE order_id=#{id} AND state='HELD'") int release(@Param("id")String id,@Param("now")long now,@Param("basis")String basis);
 @Update("UPDATE b_market_order SET business_status='CLOSED',closed_at_ms=#{now},close_basis=#{basis},review_required=0,last_error=NULL,order_version=order_version+1,updated_at_ms=#{now} WHERE order_id=#{id} AND business_status<>'CLOSED'") int closed(@Param("id")String id,@Param("now")long now,@Param("basis")String basis);
 @Update("UPDATE b_purchase_guard SET active_order_id=NULL,updated_at_ms=#{now} WHERE user_id=#{user} AND goods_id=#{goods} AND active_order_id=#{id}") int clearGuard(@Param("user")String user,@Param("goods")String goods,@Param("id")String id,@Param("now")long now);
 @Insert("INSERT INTO b_inventory_ledger(ledger_id,goods_id,kind,order_id,business_key,delta_available,before_available,after_available,before_reserved,after_reserved,before_sold,after_sold,reason,created_at_ms) VALUES(#{ledger},#{before.goodsId},'RELEASE',#{order},#{order},1,#{before.available},#{after.available},#{before.reserved},#{after.reserved},#{before.sold},#{after.sold},#{reason},#{after.updatedAt})") int releaseLedger(@Param("ledger")String ledger,@Param("order")String order,@Param("before")cn.zj.zjmarket.domain.inventory.model.entity.InventoryAccount before,@Param("after")cn.zj.zjmarket.domain.inventory.model.entity.InventoryAccount after,@Param("reason")String reason);
 @Select("SELECT order_id AS orderId,request_hash AS hash,CAST(result_json AS CHAR) AS result,result_hash AS resultHash FROM b_order_operation WHERE actor_id=#{actor} AND action=#{action} AND operation_key=#{key}") cn.zj.zjmarket.infrastructure.dao.po.OrderOperationRow operation(@Param("actor")String actor,@Param("action")String action,@Param("key")String key);
 @Insert("INSERT INTO b_order_operation(operation_id,actor_id,operation_key,order_id,action,request_hash,expected_version,reason,result_json,result_hash,created_at_ms) VALUES(#{id},#{actor},#{key},#{order},#{action},#{hash},#{version},#{reason},#{body},#{resultHash},#{now})") int operationInsert(@Param("id")String id,@Param("actor")String actor,@Param("key")String key,@Param("order")String order,@Param("action")String action,@Param("hash")String hash,@Param("version")Long version,@Param("reason")String reason,@Param("body")String body,@Param("resultHash")String resultHash,@Param("now")long now);
 @Select("SELECT request_id AS requestId,intent,started_at_ms AS startedAt,finished_at_ms AS finishedAt,COALESCE(code,'PENDING') AS code,CASE WHEN stale=1 THEN 'STALE_RESULT' ELSE 'SAFE_ATTEMPT_SUMMARY' END AS message FROM b_trade_attempt WHERE order_id=#{id} ORDER BY started_at_ms DESC,attempt_id DESC LIMIT 20") List<java.util.Map<String,Object>> attempts(String id);
 String EXCEPTIONS=" FROM b_market_order o JOIN b_trade_coordination t ON o.order_id=t.order_id WHERE (o.review_required=1 OR t.paused=1 OR t.failure_count&gt;0 OR o.business_status='CLOSING') <if test='status != null'>AND o.business_status=#{status}</if><if test='paused != null'>AND t.paused=#{paused}</if><if test='review != null'>AND o.review_required=#{review}</if>";
 @Select("<script>SELECT o.order_id AS orderId,o.business_status AS status,o.goods_id AS goodsId,o.review_required AS reviewRequired,o.last_error AS errorCode,t.paused,t.task_version AS coordinationVersion"+EXCEPTIONS+" ORDER BY o.updated_at_ms DESC,o.order_id LIMIT #{size} OFFSET #{offset}</script>") List<java.util.Map<String,Object>> exceptions(@Param("status")String status,@Param("paused")Boolean paused,@Param("review")Boolean review,@Param("size")int size,@Param("offset")long offset);
 @Select("<script>SELECT COUNT(*)"+EXCEPTIONS+"</script>") long exceptionCount(@Param("status")String status,@Param("paused")Boolean paused,@Param("review")Boolean review);
}
